package com.kfs.myfppr;

import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.location.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;import org.json.*;

public class MainActivity extends Activity{
 LinearLayout root,form; EditText serial,officer,service,designation,forest,area,obs,action,tree,wildlife; TextView gps,history; double lat=0,lon=0; Uri photoUri; File photoFile; File dataFile;
 int green=Color.rgb(27,94,32); int pad=18;
 @Override public void onCreate(Bundle b){super.onCreate(b); dataFile=new File(getFilesDir(),"patrols.json"); showLogin();}
 TextView tv(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.DKGRAY);t.setPadding(pad,pad/2,pad,pad/2);return t;}
 Button btn(String s){Button b=new Button(this);b.setText(s);return b;}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setPadding(pad,8,pad,8);e.setSingleLine(false);return e;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(248,250,248)); TextView h=tv(title,22);h.setTextColor(Color.WHITE);h.setGravity(Gravity.CENTER_VERTICAL);h.setBackgroundColor(green);h.setPadding(pad,20,pad,20);root.addView(h); ScrollView sc=new ScrollView(this);form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(pad,pad,pad,pad);sc.addView(form);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 void showLogin(){base("MY FPPR  •  Forest Patrol & Reporting");form.addView(tv("Kenya Forest Service\nOffline Field Application",20)); EditText u=field("Username");EditText p=field("Password");p.setInputType(0x81);form.addView(u);form.addView(p);Button l=btn("LOGIN");form.addView(l);form.addView(tv("Prototype username: Kibes",14));l.setOnClickListener(v->{if(u.getText().toString().trim().equalsIgnoreCase("Kibes")){home();}else Toast.makeText(this,"Use username Kibes",Toast.LENGTH_LONG).show();});}
 void home(){base("MY FPPR  •  Field Dashboard");form.addView(tv("Offline-first patrol reporting",18));Button n=btn("➕  NEW PATROL");Button h=btn("📋  PATROL HISTORY");Button e=btn("📤  EXPORT REPORTS");form.addView(n);form.addView(h);form.addView(e);n.setOnClickListener(v->newPatrol());h.setOnClickListener(v->showHistory());e.setOnClickListener(v->exportCsv());}
 void newPatrol(){base("NEW PATROL");serial=field("Patrol serial number");officer=field("Officer name");service=field("Service number");designation=field("Designation");forest=field("Forest / station");area=field("Area patrolled");obs=field("Observation");action=field("Action taken");tree=field("Tree species / forest resource");wildlife=field("Wildlife observation");gps=tv("GPS: Not captured",16);form.addView(serial);form.addView(officer);form.addView(service);form.addView(designation);form.addView(forest);form.addView(area);form.addView(gps);Button g=btn("📍  CAPTURE GPS");Button c=btn("📷  TAKE PHOTO");Button s=btn("💾  SAVE PATROL");form.addView(g);form.addView(c);form.addView(obs);form.addView(action);form.addView(tree);form.addView(wildlife);form.addView(s);g.setOnClickListener(v->captureGps());c.setOnClickListener(v->takePhoto());s.setOnClickListener(v->savePatrol());}
 void captureGps(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION},10);return;}LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);try{Location l=lm.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l==null)l=lm.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);if(l!=null){lat=l.getLatitude();lon=l.getLongitude();gps.setText(String.format(Locale.US,"GPS: %.6f, %.6f",lat,lon));}else gps.setText("GPS unavailable — move outdoors and try again");}catch(Exception e){gps.setText("GPS error");}}
 void takePhoto(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},11);return;}try{Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);startActivityForResult(i,12);}catch(Exception e){Toast.makeText(this,"Camera unavailable",Toast.LENGTH_SHORT).show();}}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==12&&resultCode==RESULT_OK&&data!=null){try{Object extra=data.getExtras()==null?null:data.getExtras().get("data");if(extra instanceof Bitmap){photoFile=new File(getFilesDir(),"photo_"+System.currentTimeMillis()+".jpg");try(FileOutputStream out=new FileOutputStream(photoFile)){((Bitmap)extra).compress(Bitmap.CompressFormat.JPEG,90,out);}Toast.makeText(this,"Photo attached to next patrol",Toast.LENGTH_SHORT).show();}}catch(Exception e){Toast.makeText(this,"Could not save photo",Toast.LENGTH_SHORT).show();}}}
 JSONArray load(){try{if(!dataFile.exists())return new JSONArray();return new JSONArray(new String(java.nio.file.Files.readAllBytes(dataFile.toPath())));}catch(Exception e){return new JSONArray();}}
 void saveJson(JSONArray a){try(java.io.FileWriter w=new java.io.FileWriter(dataFile)){w.write(a.toString(2));}catch(Exception e){}}
 void savePatrol(){try{JSONObject o=new JSONObject();o.put("serial",serial.getText().toString());o.put("date",new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date()));o.put("officer",officer.getText().toString());o.put("service",service.getText().toString());o.put("designation",designation.getText().toString());o.put("forest",forest.getText().toString());o.put("area",area.getText().toString());o.put("gps",gps.getText().toString());o.put("observation",obs.getText().toString());o.put("action",action.getText().toString());o.put("tree",tree.getText().toString());o.put("wildlife",wildlife.getText().toString());o.put("photo",photoFile==null?"":photoFile.getName());JSONArray a=load();a.put(o);saveJson(a);Toast.makeText(this,"Patrol saved offline",Toast.LENGTH_LONG).show();home();}catch(Exception e){Toast.makeText(this,"Could not save patrol",Toast.LENGTH_LONG).show();}}
 void showHistory(){base("PATROL HISTORY");JSONArray a=load();if(a.length()==0){form.addView(tv("No patrols saved yet.",18));return;}for(int i=a.length()-1;i>=0;i--){try{JSONObject o=a.getJSONObject(i);TextView t=tv(o.optString("date")+"\n"+o.optString("area")+" • "+o.optString("officer")+"\n"+o.optString("observation"),16);t.setBackgroundColor(Color.WHITE);form.addView(t);View d=new View(this);d.setLayoutParams(new LinearLayout.LayoutParams(-1,2));d.setBackgroundColor(Color.LTGRAY);form.addView(d);}catch(Exception ignored){}}}
 void exportCsv(){JSONArray a=load();if(a.length()==0){Toast.makeText(this,"No patrols to export",Toast.LENGTH_SHORT).show();return;}try{File f=new File(getExternalFilesDir(null),"MyFPPR_Patrols.csv");FileWriter w=new FileWriter(f);w.write("Date,Serial,Officer,Service,Designation,Forest,Area,GPS,Observation,Action,Tree,Wildlife\n");for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String[] k={"date","serial","officer","service","designation","forest","area","gps","observation","action","tree","wildlife"};for(int j=0;j<k.length;j++){String x=o.optString(k[j],"").replace("\"","\"\"").replace("\n"," ");w.write("\""+x+"\""+(j==k.length-1?"\n":","));}}w.close();Intent s=new Intent(Intent.ACTION_SEND);s.setType("text/plain");s.putExtra(Intent.EXTRA_SUBJECT,"My FPPR Patrol Export");s.putExtra(Intent.EXTRA_TEXT,"CSV export saved at: "+f.getAbsolutePath()+"\nOpen the My FPPR app files to retrieve the CSV.");startActivity(Intent.createChooser(s,"Share export location"));}catch(Exception e){Toast.makeText(this,"Export failed",Toast.LENGTH_LONG).show();}}
}
